    bg=grid[0][0]
    line=next(v for v in sum(grid, []) if v != bg)
    h,w=len(grid),len(grid[0])
    # Find the main horizontal frame rows and outer vertical sides by their
    # number of outline cells. The enclosed panel is bounded by those strokes.
    hrows=[y for y in range(h) if sum(v==line for v in grid[y])>=6]
    if len(hrows)>=2:
        top,bottom=min(hrows),max(hrows)
        # Regions framed by the outline: set any background or guide cells
        # in the panel interior to fill color.
        for y in range(top+1,bottom):
            for x in range(w):
                # Determine if x lies within a closed outline span on both
                # horizontal boundary rows.
                if grid[top][x]==line and grid[bottom][x]==line:
                    g[y][x]=4
                elif grid[top][x]==line and grid[bottom][x]!=line:
                    # Frame boundaries can be interrupted by attached paths;
                    # use vertical walls at this x to define the filled area.
                    pass
        # Find vertical wall pairs forming enclosed cells, then fill their
        # full interior, including any interior line crossing.
        walls=[x for x in range(w) if sum(grid[y][x]==line for y in range(h))>=3]
        for y in range(top+1,bottom):
            for a,b in zip(walls,walls[1:]):
                if all(grid[top][x]==line and grid[bottom][x]==line for x in range(a,b+1)):
                    for x in range(a+1,b): g[y][x]=4
    # Fill all enclosed background components, as in the demonstration.
    seen=set()
    for y in range(h):
        for x in range(w):
            if g[y][x]!=bg or (y,x) in seen: continue
            st=[(y,x)]; seen.add((y,x)); comp=[]; edge=False
            while st:
                a,b=st.pop(); comp.append((a,b))
                if a in (0,h-1) or b in (0,w-1): edge=True
                for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
